import numpy as np

def _ref_forward(x, W, b, s, p):
    xp = np.pad(x, ((0, 0), (p, p), (p, p)))
    f, c, k, _ = W.shape
    oh, ow = (xp.shape[1] - k) // s + 1, (xp.shape[2] - k) // s + 1
    return np.array([[[np.sum(xp[:, i * s:i * s + k, j * s:j * s + k] * W[o]) + b[o] for j in range(ow)] for i in range(oh)] for o in range(f)])

def _num_grad(f, A, h=1e-6):
    g = np.zeros_like(A)
    for i in np.ndindex(A.shape):
        keep = A[i]; A[i] = keep + h; up = f(); A[i] = keep - h; down = f(); A[i] = keep
        g[i] = (up - down) / (2 * h)
    return g

