import numpy as np


def maxpool_overlap(x, size, stride):
    x = np.asarray(x, dtype=float)
    oh = (x.shape[0] - size) // stride + 1
    ow = x.shape[1] // stride
    return np.array([[x[i * stride:i * stride + size, j * stride:j * stride + size].max() for j in range(ow)] for i in range(oh)])
